def accounts_merge(accounts):
    parent = {}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    owner = {}
    for acc in accounts:
        for e in acc[1:]:
            parent.setdefault(e, e)
            owner[e] = acc[0]
        for e in acc[2:]:
            parent[find(e)] = find(acc[1])
    groups = {}
    for e in parent:
        groups.setdefault(find(e), []).append(e)
    return sorted([owner[r]] + sorted(es) for r, es in groups.items())
